import{_ as a,o as s,c as n,a1 as t}from"./chunks/framework.DIevSSiF.js";const u=JSON.parse('{"title":"Host integration — Shadow out of the box","description":"","frontmatter":{},"headers":[],"relativePath":"reference/host-integration.md","filePath":"reference/host-integration.md"}'),i={name:"reference/host-integration.md"};function o(l,e,r,h,p,d){return s(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="host-integration-—-shadow-out-of-the-box" tabindex="-1">Host integration — Shadow out of the box <a class="header-anchor" href="#host-integration-—-shadow-out-of-the-box" aria-label="Permalink to &quot;Host integration — Shadow out of the box&quot;">​</a></h1><p>Shadow should work the moment a host opens, in any directory, with zero per-session setup: same durable board, same standing goal, proxy stance on. This page is the complete cold-start wiring for Claude Code, Codex, and Grok. Cursor&#39;s skill mount and sealed host-run are supported, but file-backed cold directive activation is explicitly unsupported until Cursor exposes a reviewed user-rule surface; Shadow does not invent <code>~/.cursor/rules</code>.</p><h2 id="_1-install-once" tabindex="-1">1. Install once <a class="header-anchor" href="#_1-install-once" aria-label="Permalink to &quot;1. Install once&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --branch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shadow-v1.0.1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --depth</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  https://github.com/firstbitelabsllc/shadow.git</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shadow</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install.sh</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">shadow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span></span></code></pre></div><p>Git, Bash, Python 3.10+ — no Node, no npm. The immutable release clone is the install; update by checking out the next GitHub Latest <code>shadow-v*</code> tag and rerunning <code>install.sh</code>. If a host mount already points somewhere else (an old global package path, say), <code>install.sh</code> repoints it.</p><p>Optional: <code>export SHADOW_PORTFOLIO_ROOT=&quot;$HOME/Development&quot;</code> (that value is the default) — the root <code>shadow status</code> falls back to when the current directory has no plan, so every entry point shows the same board.</p><h2 id="_2-the-standing-goal-—-one-installed-top-level-direction-block" tabindex="-1">2. The standing goal — one installed top-level direction block <a class="header-anchor" href="#_2-the-standing-goal-—-one-installed-top-level-direction-block" aria-label="Permalink to &quot;2. The standing goal — one installed top-level direction block&quot;">​</a></h2><p>The goal for any Shadow seat is <strong>static</strong>. It is the same text for every person, every host, every day; only what the durable plans point at changes. <code>shadow goal --install</code> owns this marker-delimited block inside <code>~/.claude/CLAUDE.md</code>, <code>~/.codex/AGENTS.md</code>, and <code>~/.grok/AGENTS.md</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>## Shadow — standing goal (static; the pointer moves, this text does not)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Outcome: act as the user&#39;s active local proxy; reconstruct what matters,</span></span>
<span class="line"><span>choose and finish valuable work, prove it, improve the method, and continue</span></span>
<span class="line"><span>without requiring the user to supervise the system.</span></span>
<span class="line"><span>Authority: this computer&#39;s private local Shadow board at \`~/.shadow\` owns global</span></span>
<span class="line"><span>project priority, entity pointers, claims, owners, and resume. Each infrastructure</span></span>
<span class="line"><span>entity&#39;s local \`PLAN.md\` under \`~/.shadow/plans/\` owns its milestones, checkpoints,</span></span>
<span class="line"><span>detail, and proof. A product repository may retain its declared release plan. Chats,</span></span>
<span class="line"><span>dashboards, worktree copies, provider-private plans, and native host plans are</span></span>
<span class="line"><span>never competing authority.</span></span>
<span class="line"><span>Hierarchy: computer → project → entity → milestone → checkpoint. A project may</span></span>
<span class="line"><span>span entities; each entity keeps its own durable plan and resume checkpoint.</span></span>
<span class="line"><span>Resume: establish one stable public seat name, run \`shadow status --by &lt;seat&gt;\`</span></span>
<span class="line"><span>from any directory, continue every claim owned by that seat, then atomically</span></span>
<span class="line"><span>claim the highest-value reachable checkpoint shown. \`shadow amp\` may project</span></span>
<span class="line"><span>only a checkpoint already claimed by that seat.</span></span>
<span class="line"><span>Stance: proxy. Never ask &quot;which project?&quot; Open the board, state the selected</span></span>
<span class="line"><span>checkpoint and why now, reconstruct intent and contradictions, challenge weak</span></span>
<span class="line"><span>assumptions, and make reversible operational calls. Ask only for credentials,</span></span>
<span class="line"><span>money, external publishing/messages, destructive action, or irrecoverable</span></span>
<span class="line"><span>product intent.</span></span>
<span class="line"><span>Capabilities: deterministically use the smallest relevant installed skill and</span></span>
<span class="line"><span>repository harness; record a native fallback when absent. Never let a plugin,</span></span>
<span class="line"><span>operator invocation, review, green suite, merge, install, or demo count as</span></span>
<span class="line"><span>proof by itself.</span></span>
<span class="line"><span>Dispatch: nothing leaves the active seat unclaimed. \`shadow throw\` commits the</span></span>
<span class="line"><span>local atomic claim before any agent, workflow, or seat starts. Fan out safe,</span></span>
<span class="line"><span>path-disjoint claims only for a declared need. A mid-flight reading is</span></span>
<span class="line"><span>not a death certificate: probe the checkpoint&#39;s proof, not a process list.</span></span>
<span class="line"><span>Proof: no completed checkpoint without its receipt; \`shadow accept --by\` is</span></span>
<span class="line"><span>the only cmd-proof flip path. Run focused falsifiers in feature lanes and</span></span>
<span class="line"><span>affected integration on trunk. Run full build, migration, story E2E,</span></span>
<span class="line"><span>adversarial, rollback, and stranger-install proof on the deterministic</span></span>
<span class="line"><span>source-testing release train—normally nightly, optionally a configured second</span></span>
<span class="line"><span>daily window, plus an early run when measured accepted-change pressure crosses</span></span>
<span class="line"><span>the checked-in Method threshold. Separate owning-plan receipts prove merged</span></span>
<span class="line"><span>origin/main, installed/deployed, and live dogfood; never infer those from CI.</span></span>
<span class="line"><span>Silent skipping fails.</span></span>
<span class="line"><span>Lifecycle: blocked → record one exact wake, return the claim, and continue</span></span>
<span class="line"><span>elsewhere. Completed/blocked orphan claim → recover it, never rework it.</span></span>
<span class="line"><span>Close/archive proven milestones within the Method&#39;s hot-plan budgets, preserve</span></span>
<span class="line"><span>provenance, retire only safe clean artifacts, mint the successor, and keep</span></span>
<span class="line"><span>draining every reachable checkpoint required by full acceptance.</span></span></code></pre></div><p>A host that loads only this block cold-starts correctly: it knows where truth lives, what to do next, that asking the person to orient it is a defect, and that work it stops watching must be written down first.</p><p><code>Dispatch</code> earned its place on 2026-08-09: two fan-outs were launched with no row, and when a mid-flight reading showed no results both were declared dead. Both were still running, and both finished with real findings. Everything the recovery needed — what was dispatched, what it should return — existed only in a chat that had already moved on.</p><h2 id="your-own-methods-beside-the-block" tabindex="-1">Your own methods beside the block <a class="header-anchor" href="#your-own-methods-beside-the-block" aria-label="Permalink to &quot;Your own methods beside the block&quot;">​</a></h2><p>The managed block carries Shadow and nothing else — the same text for every person, every host, every day. Your own top-level working methods (a release discipline, a review doctrine, a personal style contract) live <strong>beside</strong> the block in the same agent file, byte-for-byte untouched by <code>shadow goal --install</code> and <code>--remove</code>. Add them as their own sections; the installer&#39;s markers bound only Shadow&#39;s text. Nothing about your methods enters <code>shadow.yaml</code> — that file stays the two-key repo dial it is.</p><p>Cursor has no reviewed user-level file for cold directives, so nothing is written there. Paste <code>shadow goal</code> output into Cursor&#39;s User Rules yourself, or into a repo-root <code>AGENTS.md</code>, which Cursor reads.</p><h2 id="_3-what-activate-shadow-means-in-a-session" tabindex="-1">3. What &quot;activate shadow&quot; means in a session <a class="header-anchor" href="#_3-what-activate-shadow-means-in-a-session" aria-label="Permalink to &quot;3. What &quot;activate shadow&quot; means in a session&quot;">​</a></h2><ol><li>Pick one stable public seat name and run <code>shadow status --by &lt;seat&gt;</code> from anywhere. Continue every claim owned by that seat before choosing new work.</li><li>Name the highest-value reachable checkpoint and why it wins now. Run the exact <code>shadow throw ... --by &lt;seat&gt;</code> command shown to claim it atomically.</li><li>Use the returned packet yourself or dispatch only path-disjoint claimed checkpoints. <code>shadow amp</code> resumes work already owned by that seat; it never substitutes for a claim.</li><li>Close each loop in the entity&#39;s <code>PLAN.md</code> — result, proof, blocked wake, and reachable successor — while the computer board retains global coordination.</li></ol><p>A session that instead answers &quot;this workspace has no plan — which project should I attach to?&quot; has step 1 unwired: the fallback exists precisely so that sentence never needs saying.</p><h2 id="_4-voice-and-remote-seats" tabindex="-1">4. Voice and remote seats <a class="header-anchor" href="#_4-voice-and-remote-seats" aria-label="Permalink to &quot;4. Voice and remote seats&quot;">​</a></h2><p>Voice sessions and remote machines follow the same contract with one extra rule: <strong>anything discovered out-of-band is written to the owning <code>PLAN.md</code> before the session ends.</strong> A &quot;packet&quot; assembled in a chat on another machine does not exist for the fleet until it is a plan row with a proof or wake predicate; git — not the transcript — carries it home.</p><h2 id="_5-the-machine-boundary" tabindex="-1">5. The machine boundary <a class="header-anchor" href="#_5-the-machine-boundary" aria-label="Permalink to &quot;5. The machine boundary&quot;">​</a></h2><p><strong>The plan is tied to the machine.</strong> <code>SHADOW_PORTFOLIO_ROOT</code> names <em>this</em> machine&#39;s plan set; a different machine has its own (possibly empty) board. Continuity between machines is <strong>git</strong> — each repository&#39;s origin — never a synced chat, a served dashboard, or another machine&#39;s board impersonated.</p><p>A seat on a machine with no plans says exactly that — &quot;no plans on this machine; the durable plans live in their git remotes&quot; — and works through <code>git clone</code>/<code>fetch</code>. Pretending an empty machine has the fleet&#39;s board is the same defect as asking &quot;which project?&quot;: inventing state instead of reading it.</p><h2 id="_6-verify-the-wiring" tabindex="-1">6. Verify the wiring <a class="header-anchor" href="#_6-verify-the-wiring" aria-label="Permalink to &quot;6. Verify the wiring&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mktemp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">)&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">shadow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --by</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shadow-check</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Run the exact Claim command status printed, then its exact Continue command.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">shadow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # command, mounts, managed Claude/Codex/Grok block, and identity green</span></span></code></pre></div>`,24)])])}const k=a(i,[["render",o]]);export{u as __pageData,k as default};
